// One message for the whole agency, not one per clinic. A channel that
// fires six times every morning gets muted within a fortnight.
//
// Severity is by staleness, not by amount. A small sum from three weeks ago
// is a broken process; a large sum from yesterday is just Monday.

const rows = $input.all().map(i => i.json);

const money = n => '$' + Number(n || 0).toFixed(2);
const totalRisk = rows.reduce((s, r) => s + Number(r.revenue_at_risk_usd || 0), 0);
const totalCount = rows.reduce((s, r) => s + Number(r.unmarked || 0), 0);

const stale = rows.filter(r => Number(r.avg_days_stale) >= 7);

const lines = rows.map(r => {
  const days = Number(r.avg_days_stale).toFixed(0);
  const flag = Number(r.avg_days_stale) >= 7 ? ' :warning:' : '';
  return `• *${r.business_name}* — ${r.unmarked} unmarked, ${money(r.revenue_at_risk_usd)} not invoiced, avg ${days}d old${flag}`;
});

let header = `*${totalCount} appointments never marked* — ${money(totalRisk)} not invoiced`;

let footer = '_Nothing is auto-marked. Guessing an outcome to clear an alert is how a billing system starts inventing revenue._';

if (stale.length) {
  footer = `:rotating_light: *${stale.length} clinic(s) averaging a week or more.* That is a front desk that has stopped recording attendance — every other number for them is degrading with it.\n\n` + footer;
}

return [{
  json: {
    clinics: rows.length,
    total_unmarked: totalCount,
    total_at_risk_usd: Number(totalRisk.toFixed(2)),
    stale_clinics: stale.length,
    text: [header, '', ...lines, '', footer].join('\n')
  }
}];
